    parser.add_argument('--exec_out', default=None, help='Connection to the next node in the execution chain')
    parser.add_argument('--context', default=None, help='Enter text/string for context.')
    parser.add_argument('--tone', default=None, help='Enter text/string for tone.')
    parser.add_argument('--character_name_to_json', default=None, help='Enter any type of data for character_name_to_json.')
    args = parser.parse_args()
    flow_input = {}
    if args.json_input is not None:
        flow_input = json.loads(args.json_input)
    if args.json_input is None:
        if 'Start Flow' not in flow_input:
            flow_input['Start Flow'] = {}
        if args.exec_out is not None:
            flow_input['Start Flow']['exec_out'] = args.exec_out
        if args.context is not None:
            flow_input['Start Flow']['context'] = args.context
        if args.tone is not None:
            flow_input['Start Flow']['tone'] = args.tone
        if args.character_name_to_json is not None:
            flow_input['Start Flow']['character_name_to_json'] = args.character_name_to_json
    workflow_output = execute_workflow(input=flow_input, storage_backend=args.storage_backend)
    print(workflow_output)
